def transform(grid):
    # The uniform separator uses a color that appears nowhere else.
    sep = next(
        i for i, row in enumerate(grid)
        if len(set(row)) == 1
        and sum(cell == row[0] for r in grid for cell in r) == len(row)
    )

    upper = grid[:sep]
    lower = grid[sep + 1:]

    shared = ({cell for row in upper for cell in row}
              & {cell for row in lower for cell in row})
    background = max(
        shared,
        key=lambda color: sum(row.count(color) for row in upper + lower)
    )

    return [
        [3 if a == background and b == background else 2
         for a, b in zip(top_row, bottom_row)]
        for top_row, bottom_row in zip(upper, lower)
    ]
