def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid divider row.
    sep = next(
        i for i, row in enumerate(grid)
        if len(set(row)) == 1
        and all(row[0] not in other for j, other in enumerate(grid) if j != i)
    )

    top, bottom = grid[:sep], grid[sep + 1:]
    common = ({x for row in top for x in row}
              & {x for row in bottom for x in row})
    shared_color = next(iter(common))

    return [
        [3 if a == shared_color and b == shared_color else shared_color
         for a, b in zip(rt, rb)]
        for rt, rb in zip(top, bottom)
    ]
